export type KnowledgeEntityType = "Place" | "City" | "Restaurant" | "Food";

export type KnowledgeEntityStatus = "missing" | "draft" | "verified";

export type KnowledgeEntity = {
  id: string;
  name: string;
  type: KnowledgeEntityType;
  status: KnowledgeEntityStatus;
  aliases: string[];
  properties: Record<string, string>;
  sourceFile: string;
};

export type KnowledgeAlias = {
  entityId: string;
  alias: string;
  language: "vi" | "en";
};

export type KnowledgeRelationship = {
  id: string;
  fromEntityId: string;
  relationship: OntologyRelationship["type"];
  toEntityId: string;
  source: string;
};

export type OntologyNode = {
  type: KnowledgeEntityType;
  description: string | null;
};

export type OntologyRelationship = {
  type: "LOCATED_IN" | "SERVES" | "NEAR";
  from: KnowledgeEntityType | null;
  to: KnowledgeEntityType | null;
  description: string;
};

export type ValidationIssue = {
  id: string;
  severity: "error" | "warning" | "info";
  title: string;
  message: string;
  path: string;
  entityId?: string;
  target: "entities" | "aliases" | "relationships" | "ontology";
};

